const $ = id => document.getElementById(id);
const icon = name => { const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg'); const use = document.createElementNS(svg.namespaceURI, 'use'); use.setAttribute('href', '#i-' + name); svg.append(use); return svg; };
let state, csrf = '', source = '', folder, review, currentStep = 1, activeJob = null, pollTimer = null;
let historyRows = [], historyTotal = 0, historyFilter = '', historyRequest = 0, historyOffset = 0;
let selectedJob = null, jobRequest = 0;
const stages = {starting:'Starting worker',preparing:'Preparing release',duplicate_check:'Checking duplicates',screenshots:'Generating screenshots',mediainfo:'Reading media information',hashing:'Creating torrent',images:'Uploading images',description:'Preparing description',uploading:'Uploading to DigitalCore',downloading_torrent:'Downloading confirmed torrent',watch_folder_ready:'Torrent delivered',completed:'Completed',duplicate:'Duplicate found',needs_review:'Needs attention',interrupted:'Interrupted'};
const seedLabels={seeding:'Seeding',paused:'Paused',checking:'Checking',downloading:'Downloading',queued:'Queued',error:'Client error',unknown:'Status unavailable',no_clients:'No client connected',not_found:'Not found on clients',unlinked:'No torrent hash yet'};
const statuses = {running:'Uploading',completed:'Completed',duplicate:'Duplicate skipped',needs_review:'Needs attention',interrupted:'Interrupted'};
function toast(message, error = false) { $('toast').textContent = message; $('toast').classList.toggle('error', error); $('toast').hidden = false; clearTimeout(toast.timer); toast.timer = setTimeout(() => $('toast').hidden = true, error ? 8000 : 4500); }
async function api(path, data) {
  const response = await fetch(path, {credentials:'same-origin', headers:data ? {'Content-Type':'application/json','X-CSRF-Token':csrf} : {}, method:data ? 'POST' : 'GET', body:data ? JSON.stringify(data) : undefined});
  const result = await response.json();
  if (response.status === 401 && path !== '/api/login') { showLogin(); throw new Error('Sign in to continue.'); }
  if (!response.ok) throw new Error(result.error || 'Something went wrong. Please try again.');
  return result;
}
function showLogin() { $('app').hidden = true; $('login').hidden = false; if (pollTimer) clearTimeout(pollTimer); $('access-password').focus(); }
function prettySize(size) { if (!size) return '0 B'; const units = ['B','KB','MB','GB','TB']; const n = Math.min(4, Math.floor(Math.log(size)/Math.log(1024))); return (size / 1024**n).toFixed(n > 1 ? 1 : 0) + ' ' + units[n]; }
function page(name) { closeJobDetails(); document.body.classList.toggle('client-view',name==='clients'); for (const section of document.querySelectorAll('main>.page')) section.hidden = section.id !== 'page-' + name; document.querySelectorAll('.nav-item').forEach(el => el.classList.toggle('active', el.dataset.page === name)); $('breadcrumb').textContent = {upload:'New upload',activity:'Activity',settings:'Settings',clients:'Clients',imports:'Import torrent',guide:'Manuals'}[name]; if (name === 'activity') refreshActivity().catch(e => toast(e.message,true)); if(name==='settings') Promise.all([loadSecurity(),loadDeliveryClients()]).catch(e=>toast(e.message,true)); if(name==='imports') refreshImports().catch(e=>toast(e.message,true)); if(name==='clients') refreshClients().catch(e=>toast(e.message,true)); }
function step(number) { currentStep = number; document.querySelectorAll('.step-panel').forEach(el => el.hidden = el.id !== 'step-' + number); document.querySelectorAll('.step').forEach(el => {el.classList.toggle('active', Number(el.dataset.step) === number); el.classList.toggle('done',Number(el.dataset.step)<number);}); }
function updateState(next) {
  state = next; if (next.csrf) csrf = next.csrf;
  const settings = next.settings;
  renderConfigSettings(settings);
  $('metadata-ignore-words').value=(settings.metadata_ignore_words||[]).join('\n');updateCleanupExample();
  $('screenshot-engine').value=settings.screenshot_engine||'ffmpeg';
  $('status-button').replaceChildren(document.createElement('span'), document.createTextNode(next.ready ? 'Ready to upload' : 'Setup needed'));
  $('status-button').classList.toggle('needs', !next.ready); $('setup-notice').hidden = next.ready;
  $('sidebar-path').textContent = settings.content; $('preview-watch').textContent = settings.watch;
  $('content-path').value = settings.content; $('watch-path').value = settings.watch;
  $('delivery-remote').value=settings.import_remote_root||'';$('delivery-local').value=settings.import_local_root||settings.content;$('delivery-watch-label').textContent=settings.watch;
  $('content-path').readOnly = $('watch-path').readOnly = settings.paths_locked;
  $('path-help').textContent = settings.paths_locked ? 'These folders are mapped by Docker. Change the host folders in your container configuration.' : 'Paths are on the machine running the uploader. Relative paths start at the app folder.';
  if(!$('image-host').querySelector('option[value=custom]')&&settings.image_host==='custom')$('image-host').append(new Option('Existing custom host','custom'));$('image-host').value=settings.image_host||'digitalcore';$('image-host-key-state').textContent=settings.has_image_host_key?'✓ saved':'optional';
  $('tmdb-state').textContent=settings.has_tmdb_token?'✓ saved':'optional';
  $('igdb-state').textContent=settings.has_igdb_credentials?'✓ saved':'optional';
  $('key-state').textContent = settings.has_api_key ? '✓ saved securely' : 'not configured';
  $('announce-state').textContent = settings.has_announce ? '✓ saved securely' : 'not configured';
  $('api-key').placeholder = settings.has_api_key ? 'Saved — enter a value only to replace it' : 'Paste your DigitalCore API key';
  $('announce').placeholder = settings.has_announce ? 'Saved — enter a value only to replace it' : 'https://tracker…/your-personal-passkey';
  for (const [field,key] of Object.entries({'opt-images':'IMAGE_UPLOAD','opt-screenshots':'SCREENSHOTS','opt-mediainfo':'MEDIAINFO','opt-dupe':'DUPECHECK'})) $(field).checked = settings.options[key];
  $('settings-health').replaceChildren(); $('settings-health').classList.toggle('ready',next.ready);
  if (next.ready) $('settings-health').textContent = '✓ Upload prerequisites ready. Folder write access and dependencies checked. Configure seeding separately below.';
  else for (const message of next.errors) {const p=document.createElement('div'); p.textContent=message; $('settings-health').append(p);}
  if ($('category').options.length === 1) for (const row of next.categories) {const option = document.createElement('option'); option.value=row.id; option.textContent=row.name; $('category').append(option);}
  updateHistoryStats(next.history);
  if (!historyRows.length && !historyFilter) {historyRows=next.jobs; historyTotal=next.history.total; renderActivity(historyRows); historyFooter();}
}
async function boot() { try {const data = await api('/api/state'); updateState(data); $('login').hidden=true; $('app').hidden=false; if (data.active) { page('activity'); openJob(data.active); }} catch (error) { if (!state) showLogin(); else toast(error.message,true); } }
$('login-form').addEventListener('submit', async event => { event.preventDefault(); const button=event.submitter; button.disabled=true; $('login-error').textContent=''; try {await api('/api/login',{username:$('access-username').value,password:$('access-password').value}); $('access-password').value=''; await boot();} catch(error){$('login-error').textContent=error.message;} finally{button.disabled=false;} });
document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>page(el.dataset.page)));
$('logout').addEventListener('click',async()=>{try{await api('/api/logout',{});state=null;showLogin();}catch(e){toast(e.message,true);}});
$('status-button').addEventListener('click',()=>page('settings'));
$('help-button').addEventListener('click',()=>$('help').hidden=!$('help').hidden);
document.querySelectorAll('[data-step]').forEach(el=>el.addEventListener('click',()=>{const n=Number(el.dataset.step);if(n===1)step(1);else if(n===2 && source)step(2);else if(n===3 && review)step(3);else toast(n===2?'Choose a release folder first.':'Add the details and review your release first.');}));
function livePreview(){const category=$('category');$('preview-category').textContent=category.value?category.selectedOptions[0].textContent:'YOUR NEXT UPLOAD';$('preview-name').textContent=source?source.split(/[\\/]/).filter(Boolean).pop():'Something good is coming.';$('preview-folder').textContent=source?source.split(/[\\/]/).filter(Boolean).pop():'Not selected';$('preview-description').textContent=$('description').value.trim() || (source?'Add the details and give your release a little context.':'Choose a folder and your release will start taking shape here.');const urls=$('images').value.split('\n').filter(v=>v.trim());$('preview-images').textContent=urls.length?urls.length+' image URL'+(urls.length===1?'':'s'):'From release folder';}
for (const id of ['category','studio','performers','genre','year','description','images']) $(id).addEventListener('input',()=>{review=null;livePreview();});
async function openFolder(path){$('folder-list').replaceChildren();const loading=document.createElement('div');loading.className='empty-state';loading.textContent='Opening your library…';$('folder-list').append(loading);try{folder=await api('/api/folders'+(path?'?path='+encodeURIComponent(path):''));$('browser-path').textContent=folder.path;$('folder-up').disabled=!folder.parent;$('use-folder').disabled=folder.path===folder.root || (!folder.files.length && !folder.folders.length);$('folder-list').replaceChildren();for(const row of folder.folders){const button=document.createElement('button');button.type='button';button.className='folder-row';const name=document.createElement('span');name.textContent=row.name;const arrow=document.createElement('small');arrow.textContent='→';button.append(icon('folder'),name,arrow);button.addEventListener('click',()=>openFolder(row.path));$('folder-list').append(button);}for(const row of folder.files){const item=document.createElement('div');item.className='folder-row file-row';const name=document.createElement('span');name.textContent=row.name;const size=document.createElement('small');size.textContent=prettySize(row.size);item.append(icon(/\.(jpg|png|jpeg|webp|gif)$/i.test(row.name)?'image':'grid'),name,size);$('folder-list').append(item);}if(!folder.files.length&&!folder.folders.length){const empty=document.createElement('div');empty.className='empty-state';empty.textContent='This folder is empty. Add a release to your content library to get started.';$('folder-list').append(empty);}$('browser-count').textContent=folder.folders.length+' folders · '+folder.files.length+' files';}catch(e){$('folder-list').replaceChildren();const error=document.createElement('div');error.className='empty-state';error.textContent=e.message;$('folder-list').append(error);$('use-folder').disabled=true;}}
for(const id of ['choose-folder','change-folder'])$(id).addEventListener('click',()=>{$('folder-dialog').showModal();openFolder(source || state.settings.content);});
$('close-folders').addEventListener('click',()=>$('folder-dialog').close());
$('folder-up').addEventListener('click',()=>{if(folder?.parent)openFolder(folder.parent);});
$('use-folder').addEventListener('click',()=>{if(!folder || folder.path===folder.root)return;if(!folder.files.length&&!folder.folders.length)return;source=folder.path;review=null;$('selected-name').textContent=source.split(/[\\/]/).pop();$('selected-path').textContent=source;$('selected-folder').hidden=false;$('choose-folder').hidden=true;$('to-details').disabled=false;$('folder-dialog').close();livePreview();toast('Release folder selected. Let’s add the details.');});
$('to-details').addEventListener('click',()=>step(2));document.querySelector('.back-content').addEventListener('click',()=>step(1));$('back-details').addEventListener('click',()=>step(2));
function jobInput(){return {source,category:Number($('category').value),description:$('description').value,images:$('images').value.split('\n').map(v=>v.trim()).filter(Boolean),metadata:{studio:$('studio').value,performers:$('performers').value,content_tags:$('genre').value,runtime_minutes:$('runtime').value,release_year:$('year').value,imdbId:$('imdb').value,gameUrl:$('game-url').value}};}
function reviewRow(label,value){const row=document.createElement('div');const term=document.createElement('dt');term.textContent=label;const content=document.createElement('dd');content.textContent=value;row.append(term,content);$('review-fields').append(row);}
$('details-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{review=await api('/api/review',jobInput());$('review-fields').replaceChildren();reviewRow('Release',review.job.source.split(/[\\/]/).pop());reviewRow('Folder',review.job.source);reviewRow('Category',review.category_name);reviewRow('Content',review.summary.files+' files · '+prettySize(review.summary.bytes)+(review.summary.limited?' (partial scan)':''));for(const [key,value]of Object.entries(review.job.metadata))reviewRow({content_tags:'Genres / tags',release_year:'Release year'}[key]||key[0].toUpperCase()+key.slice(1),value);reviewRow('Description',review.job.description||'From the NFO in your folder, if present.');reviewRow('Images',review.job.images.length?review.job.images.join('\n'):review.summary.images+' folder images · automatic screenshots '+(state.settings.options.SCREENSHOTS?'enabled':'disabled'));reviewRow('Watch folder',review.watch);$('review-errors').hidden=review.ready;$('review-errors').textContent=review.ready?'':'Finish setup before uploading:\n'+review.errors.join('\n');$('publish').disabled=!review.ready||!!state.active;step(3);}catch(e){toast(e.message,true);}finally{button.disabled=false;}});
$('publish').addEventListener('click',async()=>{if(!review)return;$('publish').disabled=true;try{const job=await api('/api/upload',{review_id:review.review_id});review=null;page('activity');openJob(job.id);toast('Upload started. We’ll take it from here.');}catch(e){toast(e.message,true);$('publish').disabled=false;}});
$('settings-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const next=await api('/api/settings',{config_fields:collectConfigSettings(),screenshot_engine:$('screenshot-engine').value,import_client:$('delivery-client').value,import_remote_root:$('delivery-remote').value,import_local_root:$('delivery-local').value,image_host:$('image-host').value,image_host_key:$('image-host-key').value,tmdb_token:$('tmdb-token').value,igdb_client_id:$('igdb-client-id').value,igdb_client_secret:$('igdb-client-secret').value,api_key:$('api-key').value,announce:$('announce').value,content:$('content-path').value,watch:$('watch-path').value,options:{IMAGE_UPLOAD:$('opt-images').checked,SCREENSHOTS:$('opt-screenshots').checked,MEDIAINFO:$('opt-mediainfo').checked,DUPECHECK:$('opt-dupe').checked}});updateState(next);$('api-key').value='';$('announce').value='';$('tmdb-token').value='';$('igdb-client-id').value='';$('igdb-client-secret').value='';$('image-host-key').value='';review=null;toast(next.ready?'Settings saved. Your workspace is ready.':'Settings saved. Check the remaining setup items.');}catch(e){toast(e.message,true);}finally{button.disabled=false;}});
function renderActivity(jobs){
  const list=$('activity-list');list.replaceChildren();
  if(!jobs.length){const empty=element('div','empty-state');empty.append(element('h3','','No matching uploads.'),element('p','','Change your search or status filter.'));list.append(empty);return;}
  for(const job of jobs){
    const row=element('button','activity-row');row.type='button';row.title='View upload details: '+job.name;
    const image=element('span','activity-icon');image.append(icon(job.status==='completed'?'check':'clock'));
    const info=element('span','list-release');const title=element('strong','',job.name);title.title=job.name;info.append(title);
    if(job.torrent_id||job.status==='running')info.append(element('small','',job.status==='running'?(stages[job.stage]||job.stage):'Torrent #'+job.torrent_id));
    const date=element('time','list-date',new Date(job.started*1000).toLocaleString(undefined,{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}));date.dateTime=new Date(job.started*1000).toISOString();
    const seed=element('span','list-seeding',job.torrent_hash?(seedLabels[job.seeding_status]||'Unknown'):'—');
    const badge=element('span','activity-status '+job.status,statuses[job.status]||job.status);
    row.append(image,info,date,seed,badge);row.addEventListener('click',()=>{openJob(job.id);});list.append(row);
  }
}
function listCounts(id,labels,counts,total){for(const option of $(id).options)option.textContent=(labels[option.value]||option.value)+' ('+(option.value?counts[option.value]||0:total)+')';}
function updateHistoryStats(history){if(!history)return;const pending=(history.counts.running||0)+(history.counts.needs_review||0)+(history.counts.interrupted||0);const badge=$('activity-count');badge.textContent=pending;badge.hidden=pending===0;badge.title='Active uploads or uploads needing attention';$('stat-total').textContent=history.all_total;$('stat-completed').textContent=history.counts.completed;$('stat-running').textContent=history.counts.running;$('stat-attention').textContent=history.counts.needs_review+history.counts.interrupted;}
function historyFooter(){
  $('history-count').textContent=historyTotal?(historyOffset+1)+'–'+(historyOffset+historyRows.length)+' of '+historyTotal+' matching uploads':'0 matching uploads';
  $('history-more').textContent='Next →';$('history-more').hidden=historyOffset+historyRows.length>=historyTotal;$('history-prev').disabled=historyOffset===0;
}
async function loadHistory(mode='refresh'){
  const request=++historyRequest,size=Number($('history-limit').value);if(mode===true)historyOffset=0;else if(mode===false)historyOffset+=size;else if(mode==='previous')historyOffset=Math.max(0,historyOffset-size);
  const query=new URLSearchParams({limit:size,offset:historyOffset,status:historyFilter,search:$('history-search').value,sort:$('history-sort').value,direction:$('history-direction').value});
  const result=await api('/api/history?'+query);if(request!==historyRequest)return;
  if(result.total&&historyOffset>=result.total){historyOffset=Math.floor((result.total-1)/size)*size;return loadHistory();}
  historyRows=result.jobs;historyTotal=result.total;updateHistoryStats(result);renderActivity(historyRows);historyFooter();
  listCounts('history-filter',{'':'All statuses',completed:'Completed',running:'In progress',duplicate:'Duplicates',attention:'Needs attention',interrupted:'Interrupted'}, {...result.counts,attention:(result.counts.needs_review||0)+(result.counts.interrupted||0)},result.all_total);
  updateListSort('history');
}
function updateListSort(prefix){for(const button of document.querySelectorAll('[data-'+prefix+'-sort]')){const selected=button.dataset[prefix+'Sort']===$(prefix+'-sort').value;button.setAttribute('aria-pressed',String(selected));button.querySelector('.sort-arrow').textContent=selected?($(prefix+'-direction').value==='asc'?'↑':'↓'):'↕';}}
function bindListTools(prefix,reload){let timer;$(prefix+'-search').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>reload(true).catch(e=>toast(e.message,true)),250);});for(const field of ['sort','direction','limit'])$(prefix+'-'+field).addEventListener('change',()=>reload(true).catch(e=>toast(e.message,true)));$(prefix+'-prev').addEventListener('click',()=>reload('previous').catch(e=>toast(e.message,true)));for(const button of document.querySelectorAll('[data-'+prefix+'-sort]'))button.addEventListener('click',()=>{const key=button.dataset[prefix+'Sort'];$(prefix+'-direction').value=$(prefix+'-sort').value===key?($(prefix+'-direction').value==='asc'?'desc':'asc'):(['name','status'].includes(key)?'asc':'desc');$(prefix+'-sort').value=key;reload(true).catch(e=>toast(e.message,true));});}
async function refreshActivity(){const next=await api('/api/state');updateState(next);await loadHistory();}
function jobDetail(label,value){const row=document.createElement('div');const term=document.createElement('dt');term.textContent=label;const detail=document.createElement('dd');detail.textContent=value;row.append(term,detail);$('job-details').append(row);}
function showJobDetails(job){$('job-details').replaceChildren();jobDetail('Current phase',stages[job.stage]||job.stage);jobDetail('Started',new Date(job.started*1000).toLocaleString());jobDetail('Finished',job.finished?new Date(job.finished*1000).toLocaleString():'Still running');const elapsed=(job.finished||Date.now()/1000)-job.started;jobDetail('Duration',elapsed<60?Math.max(0,Math.round(elapsed))+' seconds':Math.floor(elapsed/60)+'m '+Math.floor(elapsed%60)+'s');jobDetail('DigitalCore result',{not_started:'Not submitted',pending:'Awaiting confirmation',accepted:'Accepted by DigitalCore',duplicate:'Already exists',unknown:'Unknown — check the site'}[job.site_status]||job.site_status);jobDetail('Torrent ID',job.torrent_id?'#'+job.torrent_id:'Not available');jobDetail('Seeding status',seedLabels[job.seeding_status]||'Status unavailable');if(job.torrent_hash)jobDetail('Torrent hash',job.torrent_hash);for(const client of job.clients||[])jobDetail(client.client_name,client.stale?'Offline / stale snapshot':(seedLabels[client.status]||client.state)+' · ratio '+Number(client.ratio).toFixed(2)+' · ↑ '+prettySize(client.upspeed)+'/s');if(job.source)jobDetail('Source folder',job.source);if(job.watch_torrent)jobDetail('Watch torrent',job.watch_torrent);if(job.exit_code!==null)jobDetail('Worker exit code',String(job.exit_code));jobDetail('Saved log lines',String(job.log_count));$('job-error').hidden=!job.error;$('job-error').textContent=job.error||'';$('job-timeline').replaceChildren();let previous='';for(const event of job.events||[]){if(event.stage===previous)continue;previous=event.stage;const item=document.createElement('span');item.className='timeline-step';item.append(document.createTextNode(stages[event.stage]||event.stage));const at=document.createElement('time');at.textContent=new Date(event.created*1000).toLocaleTimeString();item.append(at);$('job-timeline').append(item);}}
function renderHashProgress(job){const panel=$('hashing-progress-panel'),bar=$('hashing-progress'),label=$('hashing-progress-label');panel.hidden=job.stage!=='hashing';if(panel.hidden)return;const fraction=Number(job.hash_progress),known=job.hash_progress!=null&&Number.isFinite(fraction);if(known)bar.value=Math.max(0,Math.min(1,fraction));else bar.removeAttribute('value');label.textContent=job.hash_mode==='editing'?'mkbrr: editing existing torrent (no media hashing)':known?'mkbrr: hashing files · '+Math.round(fraction*100)+'%'+(job.hash_total?' · '+prettySize(job.hash_total):''):'mkbrr: hashing release files…';}
function closeJobDetails(){
  ++jobRequest;selectedJob=null;activeJob=null;clearTimeout(pollTimer);pollTimer=null;
  $('job-current').hidden=true;$('job-navigation').hidden=true;$('upload-history').hidden=false;
}
function openJob(id){
  clearTimeout(pollTimer);selectedJob=id;activeJob=id;const request=++jobRequest;
  $('upload-history').hidden=true;$('job-current').hidden=true;$('job-navigation').hidden=false;
  $('back-activity').focus({preventScroll:true});
  followJob(id,request);
}
$('back-activity').addEventListener('click',()=>{closeJobDetails();refreshActivity().catch(e=>toast(e.message,true));$('history-search').focus({preventScroll:true});});
async function followJob(id,request=jobRequest){clearTimeout(pollTimer);try{const job=await api('/api/jobs/'+id);if(request!==jobRequest||selectedJob!==id)return;$('job-current').hidden=false;$('job-title').textContent=job.name;$('job-status').textContent=job.status==='completed'?'Confirmed torrent delivered to the watch folder. Check that your client is seeding.':job.status==='duplicate'?'This release already exists. No new upload was published.':job.status==='running'?(stages[job.stage]||'Your server is processing this release.')+'.':job.status==='interrupted'?'The worker was interrupted. Check the site before trying again.':job.site_status==='accepted'?'DigitalCore accepted this upload, but local processing needs attention. Do not upload it again.':'Check the output and DigitalCore before retrying this release.';$('job-badge').textContent=statuses[job.status]||job.status;$('job-progress').classList.toggle('done',job.status!=='running');renderHashProgress(job);showJobDetails(job);const log=$('job-log');const nearBottom=log.scrollHeight-log.scrollTop-log.clientHeight<60;log.textContent=job.logs.join('\n');if(nearBottom)log.scrollTop=log.scrollHeight;if(job.status==='running')pollTimer=setTimeout(()=>followJob(id,request),1500);else{activeJob=null;await refreshActivity();}}catch(e){if(request===jobRequest){closeJobDetails();toast(e.message,true);}}}
$('history-filter').addEventListener('change',()=>{historyFilter=$('history-filter').value;loadHistory(true).catch(e=>toast(e.message,true));});
$('history-more').addEventListener('click',()=>loadHistory(false).catch(e=>toast(e.message,true)));
bindListTools('history',loadHistory);

let clientList=[],torrentRows=[],torrentTotal=0;
function element(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
function editClient(client={}){$('client-id').value=client.id||'';$('client-name').value=client.name||'';$('client-url').value=client.url||'';$('client-username').value=client.username||'';$('client-password').value='';$('client-password').placeholder=client.has_password?'Saved — leave blank to keep it':'';$('client-verify').checked=client.verify_ssl!==0;$('client-enabled').checked=client.enabled!==0;$('remove-client').hidden=!client.id;$('client-dialog-title').textContent=client.id?'Edit client.':'Add a client.';$('client-dialog').showModal();}
async function refreshClients(){const result=await api('/api/clients');clientList=result.clients;$('client-cards').replaceChildren();const selected=$('torrent-client-filter').value;$('torrent-client-filter').replaceChildren(new Option('All clients',''));for(const client of clientList){$('torrent-client-filter').append(new Option(client.name,client.id));const row=element('div','client-connection');const select=element('button','connection-select');select.type='button';select.append(element('span','client-online'+(client.online?'':' offline'),client.online?'●':'○'),element('strong','',client.name));select.title=client.url;select.addEventListener('click',()=>{$('torrent-client-filter').value=client.id;loadTorrents(true).catch(e=>toast(e.message,true));});const totals=element('span','connection-counts',client.torrent_count+' torrents · '+(client.counts.seeding||0)+' seeding · '+(client.counts.paused||0)+' paused');const version=element('small','',client.version||'qBittorrent');const manage=element('button','button subtle small','Manage');manage.type='button';manage.addEventListener('click',()=>editClient(client));row.append(select,totals,version,manage);if(client.error){row.append(element('span','client-error',client.error));}$('client-cards').append(row);}if(!clientList.length){const empty=element('div','client-connection');empty.append(element('span','','No clients connected. Add your NAS or seedbox WebUI.'));$('client-cards').append(empty);}$('torrent-client-filter').value=selected;await loadTorrents(true);}
function torrentFilters(){return '?client='+encodeURIComponent($('torrent-client-filter').value)+'&status='+encodeURIComponent($('torrent-state-filter').value)+'&search='+encodeURIComponent($('torrent-search').value)+'&sort='+encodeURIComponent($('torrent-sort').value)+'&direction='+encodeURIComponent($('torrent-direction').value);}
let torrentRequest=0;
async function loadTorrents(reset=true){const request=++torrentRequest;const result=await api('/api/client-torrents'+torrentFilters()+'&offset='+(reset?0:torrentRows.length));if(request!==torrentRequest)return;torrentRows=reset?result.torrents:torrentRows.concat(result.torrents);torrentTotal=result.total;$('client-torrents').replaceChildren();const table=element('table','torrent-table');const head=element('thead');const headings=element('tr');for(const [name,key] of [['Name','name'],['Client','client'],['Size','size'],['Done','progress'],['Status','status'],['↓ Download','dlspeed'],['↑ Upload','upspeed'],['Ratio','ratio'],['Added','added_on'],['Control',null]]){const th=element('th');if(key){const selected=$('torrent-sort').value===key,ascending=$('torrent-direction').value==='asc';th.setAttribute('aria-sort',selected?(ascending?'ascending':'descending'):'none');const sortButton=element('button','column-sort',name);sortButton.type='button';sortButton.setAttribute('aria-label','Sort by '+name.replace(/^[↓↑] /,''));sortButton.append(element('span','sort-arrow',selected?(ascending?'↑':'↓'):'↕'));sortButton.addEventListener('click',()=>{const current=$('torrent-sort').value===key;$('torrent-direction').value=current?($('torrent-direction').value==='asc'?'desc':'asc'):(['name','client','status'].includes(key)?'asc':'desc');$('torrent-sort').value=key;loadTorrents(true).catch(e=>toast(e.message,true));});th.append(sortButton);}else th.textContent=name;headings.append(th);}head.append(headings);table.append(head);const body=element('tbody');for(const torrent of torrentRows){const row=element('tr');const title=element('td','torrent-name',torrent.name);title.title=torrent.name+'\n'+torrent.save_path+'\n'+torrent.hash;const client=element('td','torrent-client-name',torrent.client_name);client.title=torrent.client_name;const size=element('td','number',prettySize(torrent.size));const done=element('td','torrent-completion');const progress=element('progress');progress.max=1;progress.value=torrent.progress;done.append(progress,element('span','',(torrent.progress*100).toFixed(1)+'%'));const status=element('td','');const badge=element('span','torrent-state '+(torrent.stale?'stale':torrent.status),torrent.stale?'Stale':(seedLabels[torrent.status]||torrent.state));badge.title=torrent.state;status.append(badge);const down=element('td','number',prettySize(torrent.dlspeed)+'/s');const up=element('td','number',prettySize(torrent.upspeed)+'/s');const ratio=element('td','number',Number(torrent.ratio).toFixed(2));const added=element('td','torrent-added');const addedDate=Number(torrent.added_on)>0?new Date(Number(torrent.added_on)*1000):null;added.textContent=addedDate&&!Number.isNaN(addedDate.getTime())?addedDate.toLocaleString(undefined,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';added.title=addedDate&&!Number.isNaN(addedDate.getTime())?addedDate.toLocaleString():'Added date unavailable';const actions=element('td','torrent-control');const action=torrent.status==='paused'?'resume':'pause';const button=element('button','torrent-action',action==='resume'?'▶':'Ⅱ');button.type='button';button.title=(action==='resume'?'Resume ':'Pause ')+torrent.name;button.setAttribute('aria-label',(action==='resume'?'Resume ':'Pause ')+torrent.name);button.disabled=torrent.stale;button.addEventListener('click',async()=>{button.disabled=true;try{const result=await api('/api/clients/action',{id:torrent.client_id,hash:torrent.hash,action});if(!result.ok)throw new Error(result.error);await refreshClients();}catch(e){toast(e.message,true);button.disabled=false;}});actions.append(button);row.append(title,client,size,done,status,down,up,ratio,added,actions);body.append(row);}table.append(body);$('client-torrents').append(table);if(!torrentRows.length){const empty=element('div','empty-state');empty.append(element('h3','','No torrents to show.'),element('p','','Connect a client, or change the filters.'));$('client-torrents').append(empty);}$('torrent-count').textContent=torrentRows.length+' of '+torrentTotal+' torrents';$('torrent-more').hidden=torrentRows.length>=torrentTotal;}
