let metadataPreviewVersion=0;
function resetMetadataPreview(){metadataPreviewVersion++;$('metadata-dialog').classList.remove('metadata-detail-view');$('metadata-preview').hidden=true;$('metadata-preview').replaceChildren();$('metadata-search').hidden=false;$('metadata-results').hidden=false;}
function showMetadataPreview(detail,candidates=[],chosenSources=null){
 const primary=detail,sourceKey=row=>row.url||row.site+':'+row.title;
 const sources=[primary,...candidates.filter(row=>sourceKey(row)!==sourceKey(primary))];
 const activeSources=chosenSources||new Set(sources.filter(row=>row===primary||CatalogMetadata.sameRelease(primary,row)).map(sourceKey));
 const selected=sources.filter(row=>activeSources.has(sourceKey(row)));
 detail=CatalogMetadata.combine(selected);
 const version=++metadataPreviewVersion, panel=$('metadata-preview');
 $('metadata-dialog').classList.add('metadata-detail-view');panel.replaceChildren();panel.hidden=false;$('metadata-search').hidden=true;$('metadata-results').hidden=true;
 const back=element('button','button subtle small','← Back to results');back.type='button';back.addEventListener('click',resetMetadataPreview);
 const heading=element('div','metadata-preview-heading');heading.append(back,element('h3','',detail.title||'Release preview'),element('p','field-help','Check the details and images below. Your upload fields stay unchanged until you choose Use metadata.'));
 if(detail.url){try{const u=new URL(detail.url);if(u.protocol==='https:'){const link=element('a','text-button','View source ↗');link.href=u.href;link.target='_blank';link.rel='noopener noreferrer';heading.append(link);}}catch{}}
 if(sources.length>1){
  const sourceBox=element('fieldset','metadata-source-picker');sourceBox.append(element('legend','','Contributing results'),element('p','field-help','Only matching titles with compatible known studio/year are selected automatically. Check each result before including it. Changing sources rebuilds this preview; upload fields stay unchanged.'));
  for(const row of sources){const label=element('label','metadata-source-option'),check=document.createElement('input');check.type='checkbox';check.checked=activeSources.has(sourceKey(row));check.addEventListener('change',()=>{if(check.checked)activeSources.add(sourceKey(row));else activeSources.delete(sourceKey(row));showMetadataPreview(primary,sources,activeSources);});label.append(check,element('span','',CatalogMetadata.sourceLabel(row)+' · '+row.title+(row.score==null?'':' · '+row.score+'% match')));if(row.url){try{const u=new URL(row.url);if(u.protocol==='https:'){const link=element('a','text-button','Source ↗');link.href=u.href;link.target='_blank';link.rel='noopener noreferrer';label.append(link);}}catch{}}sourceBox.append(label);}
  if(selected.some(row=>row!==primary&&!CatalogMetadata.sameRelease(primary,row)))sourceBox.append(element('p','field-error','Selected sources have different titles, studio or year. Verify every field before using this combination.'));
  heading.append(sourceBox);
 }
 if(primary.source==='catalogue'){const compare=element('button','button subtle small','Compare other catalogues');compare.type='button';compare.addEventListener('click',()=>{resetMetadataPreview();$('metadata-provider').value='auto';$('metadata-kind').hidden=true;$('metadata-query').value=primary.title;$('metadata-search').requestSubmit();});heading.append(compare);}
 panel.append(heading);
 const grid=element('div','metadata-preview-fields'), fields={}, values=detail.metadata||{};
 for(const [key,label,value,multi] of [['title','Title',detail.title],['imdbId','IMDb ID',values.imdbId],['gameUrl','Game page',values.gameUrl],['studio','Production',values.studio],['performers','Cast',values.performers],['content_tags','Genres / tags',values.content_tags],['release_year','Release year',values.release_year],['runtime_minutes','Runtime (minutes)',values.runtime_minutes],['description','Description',detail.description,true]]){
  if(key==='gameUrl'&&detail.kind!=='game'||key==='imdbId'&&detail.kind==='game')continue;
  const wrap=element('div',key==='description'?'metadata-preview-wide':''),labelNode=element('label','',label),input=document.createElement(multi?'textarea':'input');input.id='metadata-preview-'+key;labelNode.htmlFor=input.id;if(multi)input.rows=5;input.value=value||'';fields[key]=input;wrap.append(labelNode,input);
  const options=detail.choices[key]||[],provenance=element('small','metadata-field-source',(detail.fieldSources[key]||[]).join(' + ')||'Not found');
  if(options.length>1){const select=document.createElement('select');select.setAttribute('aria-label',label+' source');for(const [index,option] of options.entries())select.append(new Option(option.value+' — '+option.sources.join(' + '),index));select.addEventListener('change',()=>{const option=options[Number(select.value)];input.value=option.value;provenance.textContent=option.sources.join(' + ');});wrap.append(select);}
  input.addEventListener('input',()=>{provenance.textContent='Edited manually';});wrap.append(provenance);grid.append(wrap);
 }
 panel.append(grid,element('h3','metadata-images-title','Images'),element('p','field-help','Select the images to import. Click an image to enlarge it.'));
 const gallery=element('div','metadata-preview-gallery'),images=[];
 for(const raw of (detail.images||[]).slice(0,16)){try{const u=new URL(raw);if(u.protocol==='https:'&&!u.username&&!u.password&&!images.some(i=>i.url===u.href))images.push({url:u.href});}catch{}}
 for(const [index,item] of images.entries()){
  const card=element('div','metadata-image-card'),toggle=element('label','metadata-image-toggle'),check=document.createElement('input');check.type='checkbox';check.checked=true;item.check=check;toggle.append(check,document.createTextNode('Include image '+(index+1)));
  const zoom=element('button','metadata-image-zoom');zoom.type='button';zoom.disabled=true;zoom.setAttribute('aria-label','Enlarge image '+(index+1));const image=document.createElement('img');image.alt='Release image '+(index+1);image.hidden=true;zoom.append(image);const status=element('p','field-help','Loading preview…');status.setAttribute('role','status');item.image=image;item.zoom=zoom;item.status=status;
  zoom.addEventListener('click',()=>{const dialog=$('metadata-image-dialog');$('metadata-large-image').src=image.src;$('metadata-large-image').alt=image.alt;dialog.showModal();});card.append(toggle,zoom,element('small','metadata-field-source',(detail.imageSources[item.url]||[]).join(' + ')),status);gallery.append(card);
 }
 if(!images.length)gallery.append(element('p','field-help','No images found for this release. You can add your own after importing the details.'));
 panel.append(gallery);
 const footer=element('div','metadata-preview-footer'),cancel=element('button','button subtle','Back to results'),apply=element('button','button primary','Use metadata');cancel.type=apply.type='button';apply.disabled=selected.length===0;cancel.addEventListener('click',resetMetadataPreview);
 apply.addEventListener('click',()=>{
  const prefix=metadataTarget==='imports'?'import-':'';
  for(const [id,key] of [['imdb','imdbId'],['game-url','gameUrl'],['studio','studio'],['performers','performers'],['genre','content_tags'],['year','release_year'],['runtime','runtime_minutes']])$(prefix+id).value=fields[key]?.value.trim()||'';
  $(prefix+'description').value=fields.description.value.trim();$(prefix+'images').value=images.filter(i=>i.check.checked).map(i=>i.url).join('\n');
  review=null;metadataPreviewVersion++;$('metadata-dialog').close();livePreview();toast('Selected metadata and images filled. You can still edit the upload.');
 });footer.append(cancel,apply);panel.append(footer);panel.scrollIntoView({block:'start'});
 let next=0;
 async function loadImages(){while(next<images.length&&version===metadataPreviewVersion){const item=images[next++];try{const result=await api('/api/images/preview',{url:item.url});if(version!==metadataPreviewVersion)return;item.image.src=result.image;item.image.hidden=false;item.zoom.disabled=false;item.status.textContent='';}catch(error){if(version!==metadataPreviewVersion)return;item.check.checked=false;item.status.textContent='Preview unavailable. Image excluded; select it manually to keep the link. '+error.message;}}}
 loadImages();loadImages();
}
