let metadataTarget='upload';
function openMetadata(target){resetMetadataPreview();metadataTarget=target;$('metadata-results').replaceChildren();$('metadata-message').textContent='Choose TMDB for movies/TV, IGDB for games or TVmaze for series. Review a match before applying its details.';$('metadata-query').value=target==='imports'?($('import-file').files[0]?.name.replace(/\.torrent$/i,'')||''):(source.split(/[\\/]/).pop()||'');$('metadata-query').value=SearchTitles.normalize($('metadata-query').value,state?.settings.metadata_ignore_words||[]);const categoryId=Number($(target==='imports'?'import-category':'category').value);const categoryName=state?.categories.find(c=>c.id===categoryId)?.name||'';const game=categoryName.startsWith('Games/');const television=categoryName.startsWith('Tv/');$('metadata-kind').value=television?'tv':'movie';$('metadata-provider').value=game?'igdb':television&&!state.settings.has_tmdb_token?'tvmaze':'tmdb';$('metadata-kind').hidden=$('metadata-provider').value!=='tmdb';$('metadata-dialog').showModal();}
$('lookup-upload').addEventListener('click',()=>openMetadata('upload'));
$('lookup-import').addEventListener('click',()=>openMetadata('imports'));
