$('metadata-search').addEventListener('submit',async event=>{
 event.preventDefault();$('search-metadata').disabled=true;$('metadata-results').replaceChildren();$('metadata-message').textContent='Searching '+({igdb:'IGDB',tmdb:'TMDB',tvmaze:'TVmaze'}[$('metadata-provider').value])+'…';
 try{
  const query=SearchTitles.normalize($('metadata-query').value,state?.settings.metadata_ignore_words||[]);$('metadata-query').value=query;
  const provider=$('metadata-provider').value;const kind=provider==='igdb'?'game':provider==='tvmaze'?'tv':$('metadata-kind').value;const result=await api('/api/'+provider+'/search',{query,kind});
  $('metadata-message').textContent=result.results.length?'Choose the correct title and year.':'No matches. Try the title without release tags.';
  for(const match of result.results){
   const row=element('div','metadata-result'),info=element('div');info.append(element('strong','',match.title),element('p','',[match.date,kind==='game'?'Game':kind==='tv'?'TV series':'Movie'].filter(Boolean).join(' · ')));
   const choose=element('button','button subtle small','Preview details');choose.type='button';
   choose.addEventListener('click',async()=>{choose.disabled=true;const version=metadataPreviewVersion;try{const detail=await api('/api/'+provider+'/detail',{id:match.id,kind});if(version===metadataPreviewVersion&&$('metadata-dialog').open)showMetadataPreview(detail);}catch(error){toast(error.message,true);}finally{choose.disabled=false;}});
   row.append(info,choose);$('metadata-results').append(row);
  }
 }catch(error){$('metadata-message').textContent=error.message;}finally{$('search-metadata').disabled=false;}
});
let importRows=[],importOffset=0,importRequest=0;
async function refreshImports(mode='refresh'){
  const request=++importRequest,size=Number($('imports-limit').value);if(mode===true)importOffset=0;else if(mode===false)importOffset+=size;else if(mode==='previous')importOffset=Math.max(0,importOffset-size);
  const query=new URLSearchParams({limit:size,offset:importOffset,status:$('imports-filter').value,search:$('imports-search').value,sort:$('imports-sort').value,direction:$('imports-direction').value});
  const [queue,connections]=await Promise.all([api('/api/imports?'+query),api('/api/clients')]);if(request!==importRequest)return;
  if(queue.total&&importOffset>=queue.total){importOffset=Math.floor((queue.total-1)/size)*size;return refreshImports();}
  const selected=$('import-client').value;$('import-client').replaceChildren(new Option('Choose a connected client…',''));for(const client of connections.clients.filter(c=>c.enabled))$('import-client').append(new Option(client.name+(client.online?'':' (offline)'),client.id));$('import-client').value=selected||state.settings.import_client||'';if(!$('import-client').value&&connections.clients.filter(c=>c.enabled).length===1)$('import-client').value=connections.clients.find(c=>c.enabled).id;
  if(!$('import-local').value)$('import-local').value=state.settings.import_local_root||state.settings.content;if(!$('import-remote').value)$('import-remote').value=state.settings.import_remote_root||'';if($('import-category').options.length===1)for(const cat of state.categories)$('import-category').append(new Option(cat.name,cat.id));
  importRows=queue.imports;renderImports(importRows);
  listCounts('imports-filter',{'':'All statuses',active:'Active',completed:'Completed',attention:'Needs attention',cancelled:'Cancelled',duplicate:'Duplicates'},queue.counts,queue.all_total);
  $('imports-count').textContent=queue.total?(importOffset+1)+'–'+(importOffset+importRows.length)+' of '+queue.total+' matching imports':'0 matching imports';$('imports-prev').disabled=importOffset===0;$('imports-more').hidden=importOffset+importRows.length>=queue.total;updateListSort('imports');
}
function renderImports(items){
  const list=$('import-list');list.replaceChildren();if(!items.length){const empty=element('div','empty-state');empty.append(element('h3','','No matching imports.'),element('p','','Change your filters or add a torrent above.'));list.append(empty);return;}
  const labels={adding:'Adding to client',downloading:'Downloading',waiting:'Waiting',publishing:'Starting upload',uploaded:'Upload started',cancelled:'Cancelled',needs_review:'Needs attention'};
  for(const item of items){
    const row=element('article','import-row');const info=element('div','list-release');const title=element('strong','',item.name);title.title=item.name;const path=element('small','',item.local_path);path.title=item.local_path;info.append(title,path);
    const date=element('time','list-date',new Date(item.created*1000).toLocaleString(undefined,{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}));
    const completion=element('div','list-completion');const progress=element('progress');progress.max=1;progress.value=item.progress;progress.setAttribute('aria-label','Download progress for '+item.name);completion.append(progress,element('span','',(item.progress*100).toFixed(1)+'%'));
    const status=item.upload_status||item.status,badge=element('span','import-state '+status,(statuses[status]||labels[status]||status)),actions=element('div','list-actions');
    if(item.job_id){const history=element('button','text-button','View history');history.type='button';history.addEventListener('click',()=>{page('activity');openJob(item.job_id);});actions.append(history);}
    else if(['downloading','waiting','needs_review'].includes(item.status)){
      if(item.status==='needs_review'){const resume=element('button','text-button','Check & resume');resume.type='button';resume.addEventListener('click',async()=>{try{await api('/api/imports/reconcile',{id:item.id});await refreshImports();toast('Source torrent confirmed. Automatic upload resumed.');}catch(e){toast(e.message,true);}});actions.append(resume);}
      const cancel=element('button','text-button','Cancel');cancel.type='button';cancel.setAttribute('aria-label','Cancel auto-upload for '+item.name);cancel.addEventListener('click',async()=>{try{await api('/api/imports/cancel',{id:item.id});await refreshImports();toast('Auto-upload cancelled. The original torrent stays on your client.');}catch(e){toast(e.message,true);}});actions.append(cancel);
    }
    row.append(info,date,completion,badge,actions);if(item.error&&!['cancelled','completed','duplicate'].includes(status)){const error=element('p','queue-error',item.error);error.title=item.error;row.append(error);}list.append(row);
  }
}
