$('imports-more').addEventListener('click',()=>refreshImports(false).catch(e=>toast(e.message,true)));

$('refresh-imports').addEventListener('click',()=>refreshImports().catch(e=>toast(e.message,true)));
$('import-form').addEventListener('submit',async e=>{e.preventDefault();const file=$('import-file').files[0],magnet=$('import-magnet').value.trim();if(Boolean(file)===Boolean(magnet)){toast('Choose one torrent file OR one magnet link.',true);return;}if(file&&file.size>4*1024*1024){toast('Choose a torrent file smaller than 4 MB.',true);return;}$('import-error').hidden=true;$('import-error').textContent='';$('start-import').disabled=true;try{let encoded='';if(file)encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Could not read the torrent file.'));reader.readAsDataURL(file);});await api('/api/imports/add',{torrent:encoded,magnet,client_id:$('import-client').value,remote_root:$('import-remote').value,local_root:$('import-local').value,category:Number($('import-category').value),description:$('import-description').value,images:$('import-images').value.split('\n').map(v=>v.trim()).filter(Boolean),metadata:{studio:$('import-studio').value,performers:$('import-performers').value,content_tags:$('import-genre').value,imdbId:$('import-imdb').value,gameUrl:$('import-game-url').value,runtime_minutes:$('import-runtime').value,release_year:$('import-year').value}});$('import-file').value='';$('import-magnet').value='';$('import-consent').checked=false;toast('Torrent added. Automatic upload is scheduled after download completion.');await refreshImports();}catch(error){$('import-error').textContent=error.message;$('import-error').hidden=false;toast(error.message,true);await refreshImports().catch(()=>{});}finally{$('start-import').disabled=false;}});
setInterval(()=>{if(state&&!$('page-imports').hidden)refreshImports().catch(()=>{});},10000);
boot();

async function loadSecurity(){const value=await api('/api/security');$('security-username').value=value.username;$('security-ips').value=value.allowed_ips.join('\n');$('security-peer').textContent='Your connection IP: '+value.current_ip;}
$('security-form').addEventListener('submit',async e=>{e.preventDefault();$('save-security').disabled=true;try{const result=await api('/api/security',{username:$('security-username').value,password:$('security-password').value,current_password:$('security-current').value,allowed_ips:$('security-ips').value});$('security-password').value='';$('security-current').value='';$('access-username').value=result.username;state=null;csrf='';showLogin();toast('Access settings saved. Sign in again.');}catch(error){toast(error.message,true);}finally{$('save-security').disabled=false;}});

for(const site of CatalogMetadata.sites)$('metadata-provider').append(new Option(site.name,site.name));
$('metadata-provider').addEventListener('change',()=>{$('metadata-kind').hidden=$('metadata-provider').value!=='tmdb';});
async function encodeImageFile(file){if(file.size>8*1024*1024)throw new Error('Choose images up to 8 MB each.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Could not read the selected image.'));reader.readAsDataURL(file);});}
function appendImageURL(prefix,url){const field=$(prefix+'images');field.value=[...new Set(field.value.split('\n').map(v=>v.trim()).filter(Boolean).concat(url))].join('\n');review=null;livePreview();}
for(const prefix of ['', 'import-']){
 $(prefix+'upload-images').addEventListener('click',async()=>{const files=[...$(prefix+'image-files').files];if(!files.length){toast('Choose image files first.',true);return;}if(files.length>10){toast('Upload at most 10 images at a time.',true);return;}const button=$(prefix+'upload-images');button.disabled=true;let count=0;try{for(const file of files){$(prefix+'image-upload-status').textContent='Uploading '+(count+1)+' of '+files.length+'…';const result=await api('/api/images/upload',{filename:file.name,image:await encodeImageFile(file)});appendImageURL(prefix,result.url);count++;}$(prefix+'image-files').value='';$(prefix+'image-upload-status').textContent=count+' image(s) uploaded. Links added below.';toast('Image links added.');}catch(error){$(prefix+'image-upload-status').textContent=count+' image(s) uploaded. '+error.message;toast(error.message,true);}finally{button.disabled=false;}});
 $(prefix+'rehost-images').addEventListener('click',async()=>{const field=$(prefix+'images'),urls=[...new Set(field.value.split('\n').map(v=>v.trim()).filter(Boolean))];if(!urls.length){toast('Add image URLs or choose metadata with covers first.',true);return;}if(urls.length>10){toast('Rehost at most 10 image URLs at a time.',true);return;}const button=$(prefix+'rehost-images');button.disabled=true;let count=0;try{for(const url of urls){$(prefix+'image-upload-status').textContent='Rehosting '+(count+1)+' of '+urls.length+'…';const result=await api('/api/images/rehost',{url});field.value=field.value.split('\n').map(v=>v.trim()===url?result.url:v).join('\n');count++;review=null;}livePreview();$(prefix+'image-upload-status').textContent=count+' image(s) rehosted. Links updated below.';}catch(error){$(prefix+'image-upload-status').textContent=count+' image(s) rehosted. '+error.message;toast(error.message,true);}finally{button.disabled=false;}});
}

async function loadDeliveryClients(){const result=await api('/api/clients');const selected=$('delivery-client').value||state.settings.import_client||'';$('delivery-client').replaceChildren(new Option('Choose in each import…',''));for(const client of result.clients.filter(c=>c.enabled))$('delivery-client').append(new Option(client.name+(client.online?'':' (offline)'),client.id));$('delivery-client').value=selected;}
$('check-delivery').addEventListener('click',async()=>{$('check-delivery').disabled=true;$('delivery-result').textContent='Connecting and checking existing completed files…';try{const result=await api('/api/delivery/check',{client_id:$('delivery-client').value,remote_root:$('delivery-remote').value,local_root:$('delivery-local').value});$('delivery-result').textContent=result.message;$('delivery-result').dataset.status=result.status;}catch(error){$('delivery-result').textContent=error.message;$('delivery-result').dataset.status='mismatch';}finally{$('check-delivery').disabled=false;}});
for(const id of ['delivery-client','delivery-remote','delivery-local'])$(id).addEventListener('input',()=>{$('delivery-result').textContent='Settings changed. Test this client and mapping before scheduling imports.';$('delivery-result').dataset.status='unverified';});
